import {test} from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
import {COLORS,PATTERNS,EYES,HATS,normalizeAppearance,validAppearance,loadAppearance,rememberAppearance,skinFor,patternFor,appearanceLayers,DEFAULT_APPEARANCE} from '../src/presentation/cosmetics';
import {paintFrogCore,paintFrogIdentity,paintHat,hatAnchor,paintPattern,appearancePreview} from '../src/presentation/cosmetic-art';import {SVGGraphics} from '../src/presentation/svg-graphics';
import {Customization} from '../src/ui/customization';
const recorder=()=>{const calls:any[]=[];const g=new Proxy({},{get:(_,k:string)=>(...args:any[])=>{calls.push([k,...args]);return g;}});return {g:g as any,calls};};
test('earlier server echoes cannot replace a newer cosmetic draft during quick successive edits',()=>{const editor=Object.create(Customization.prototype) as any;const baseline=normalizeAppearance({skin:'coral',eyes:'joyful',hat:'none',pattern:'spots'}),latest=normalizeAppearance({...baseline,skin:'mint',pattern:'patches',eyes:'wink',hat:'mushroom'});let paints=0;editor.value=latest;editor.signature=JSON.stringify(baseline);editor.pending=JSON.stringify(latest);editor.selects=[{disabled:false}];editor.paint=()=>paints++;for(const earlier of[baseline,{...baseline,skin:'mint'},{...baseline,skin:'mint',pattern:'patches'},{...latest,hat:'none'}]){editor.update(earlier,true);assert.deepEqual(editor.value,latest);assert.equal(paints,0);}editor.update(latest,true);assert.equal(editor.pending,'');assert.equal(paints,1);assert.deepEqual(editor.value,latest);editor.pending=JSON.stringify({...latest,hat:'bow'});editor.update(baseline,false);assert.equal(editor.pending,'');assert.equal(editor.selects[0].disabled,true);assert.deepEqual(editor.value,baseline);});
test('independent colors and ten distinct designs validate all 8,000 appearance combinations',()=>{assert.equal(COLORS.length,10);assert.equal(PATTERNS.length,10);assert.equal(EYES.length,8);assert.equal(HATS.length,10);for(const skin of COLORS)for(const pattern of PATTERNS)for(const eyes of EYES)for(const hat of HATS){const a={skin:skin.id,pattern:pattern.id,eyes:eyes.id,hat:hat.id};assert.ok(validAppearance(a));assert.deepEqual(normalizeAppearance(a),a);assert.equal(skinFor(a).color,skin.color);assert.equal(patternFor(a).id,pattern.id);}const designs=new Set(PATTERNS.map(pattern=>{const {g,calls}=recorder();paintPattern(g,0,0,13.5,{...DEFAULT_APPEARANCE,pattern:pattern.id});return JSON.stringify(calls);}));assert.equal(designs.size,10);});
test('old saved styles migrate to their original pattern; selecting a new color never changes an explicit design',()=>{for(const color of COLORS){const legacy={skin:color.id,eyes:'sleepy' as const,hat:'mushroom' as const};assert.equal(normalizeAppearance(legacy).pattern,color.pattern);for(const other of COLORS)assert.equal(normalizeAppearance({...normalizeAppearance(legacy),skin:other.id}).pattern,color.pattern);}for(const pattern of ['invalid','<svg>',4,null]){assert.ok(!validAppearance({...DEFAULT_APPEARANCE,pattern}));assert.deepEqual(normalizeAppearance({...DEFAULT_APPEARANCE,pattern}),DEFAULT_APPEARANCE);}assert.deepEqual(Object.keys(normalizeAppearance({...DEFAULT_APPEARANCE,velocity:999})).sort(),['eyes','hat','pattern','skin']);});
test('saved independent choices persist; blocked or malformed storage still allows a frog',()=>{const prior=Object.getOwnPropertyDescriptor(globalThis,'localStorage');const memory=new Map<string,string>();Object.defineProperty(globalThis,'localStorage',{configurable:true,value:{getItem:(k:string)=>memory.get(k)??null,setItem:(k:string,v:string)=>memory.set(k,v)}});try{const a=normalizeAppearance({skin:'berry',pattern:'lightning',eyes:'joyful',hat:'sprout'});rememberAppearance(a);assert.deepEqual(loadAppearance(),a);memory.set('frog-out-appearance-v1','bad JSON');assert.deepEqual(loadAppearance(),DEFAULT_APPEARANCE);Object.defineProperty(globalThis,'localStorage',{configurable:true,get(){throw Error('blocked');}});rememberAppearance(a);assert.deepEqual(loadAppearance(),DEFAULT_APPEARANCE);}finally{if(prior)Object.defineProperty(globalThis,'localStorage',prior);else delete(globalThis as any).localStorage;}});
test('portrait and neutral gameplay draw the same body, pattern, eyes and hat commands',()=>{for(const pattern of PATTERNS)for(const hat of HATS)for(const eyes of EYES){const a={skin:'coral' as const,pattern:pattern.id,eyes:eyes.id,hat:hat.id},preview=recorder(),game=recorder();paintFrogIdentity(preview.g,a);paintFrogCore(game.g,0,0,13.5,a,{sx:1,sy:1,feet:0,online:true,showPattern:true,facing:1,charging:false,openMouth:false});paintHat(game.g,0,hatAnchor(13.5,a.hat),13.5,a.hat,0);assert.deepEqual(preview.calls,game.calls);}const cpuEditor=readFileSync('src/ui/cpu-lobby.ts','utf8');assert.match(cpuEditor,/normalizeAppearance\(\{\.\.\.normalizeAppearance\(p.appearance\),\[key\]:select.value\}\)/);const source=readFileSync('src/presentation/courtyard.ts','utf8');assert.match(source,/paintFrogCore\(g,x,y,r,layers.appearance/);assert.match(source,/paintHat\(g,x,y\+hatAnchor\(r,layers.hat\)/);assert.doesNotMatch(source,/const mark=slot%8/);});
test('SVG portraits use the identical renderer, with all hats inside the viewport and no eye overlap',()=>{for(const hat of HATS){const a={...DEFAULT_APPEARANCE,hat:hat.id},g=new SVGGraphics();paintFrogIdentity(g as any,a);assert.ok(appearancePreview(a).includes(g.markup()));const calls=recorder();paintHat(calls.g,0,hatAnchor(13.5,hat.id),13.5,hat.id,0);const hatBottom=hat.id==='mushroom'?hatAnchor(13.5,hat.id)+2:hat.id==='party'?hatAnchor(13.5,hat.id)+2.5:0;if(['mushroom','party'].includes(hat.id))assert.ok(hatBottom<-13.5*.67,'hat clears pupil and upper face');assert.doesNotMatch(appearancePreview(a),/undefined|NaN|https?:/);}});
test('poison status retains priority without changing selected identity or special-size transforms',()=>{for(const state of ['healthy','transforming','infectious'])for(const hat of HATS){const a={skin:'orchid' as const,pattern:'constellation' as const,eyes:'wink' as const,hat:hat.id},before=JSON.stringify(a),layers=appearanceLayers(a,state,true);assert.equal(layers.showPattern,state==='healthy');assert.equal(layers.hat,'none');assert.equal(JSON.stringify(a),before);assert.deepEqual(layers.appearance,a);}const source=readFileSync('src/presentation/courtyard.ts','utf8');assert.match(source,/g.scaleCanvas\(size\*\(f.balloonScale\?\?1\),size\*\(f.balloonScale\?\?1\)\)/);assert.match(source,/if\(infection\?\.patientZero\)/);});
